import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Equivalenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fm/fm.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fm/fm.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fm/fm.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="equivalenza" tabindex="-1">Equivalenza <a class="header-anchor" href="#equivalenza" aria-label="Permalink to “Equivalenza”">​</a></h1><p>Dobbiamo ora procedere vedendo in cosa le figure possono essere uguali: abbiamo due possibilità: o figure con la stessa superficie (equivalenza o equiestensione) oppure figure con la stessa forma (similitudine).</p><blockquote><p>Equiestensione ed equivalenza, anche se li useremo entrambe indifferentemente, hanno un significato leggermente diverso:</p><ul><li>si parla di equiestensione quando si parla senza riferimento a misure</li><li>si parla di equivalenza quando si fa riferimento anche a misure</li></ul></blockquote><p>Cominciamo ora a parlare di figure che hanno la stessa superficie.</p><p>Considereremo come concetto primitivo l&#39;avere la stessa superficie; intuitivamente due figure avranno la stessa superficie se, per dipingerle, occorrerà la stessa quantità di vernice.</p><p>Anche se non è del tutto esatto io preferisco parlare di equivalenza, tu usa la notazione del tuo Prof.</p><ul><li><a href="./fma.html">Equiestensione</a></li><li><a href="./fmb.html">Equiscomponibilità</a></li><li><a href="./fmc.html">Applicazioni</a></li></ul>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};